  border-radius: 32px; 
  background: var(--card-bg); 
  box-shadow: 0 10px 40px var(--shadow);
}

.eyebrow { 
  color: var(--accent-color); 
  font-size: 13px; 
  letter-spacing: .2em; 
  font-weight: 800; 
