  margin: 40px 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  padding: 40px 0;
}

section {
  margin-bottom: 30px;
}

h2 {
  font-size: 1.5rem;
  margin-bottom: 10px;
  color: var(--accent-color);
}

p { 
  line-height: 1.8; 
  color: var(--text-muted); 
  margin-bottom: 1.5rem;
  font-size: 1.1rem;
}

.appreciation-list {
  margin-bottom: 1.5rem;
  padding-left: 20px;
  color: var(--text-muted);
}

.appreciation-list li {
  margin-bottom: 10px;
}

.hidden {
  display: none;
}

button#hello, button#hello-about { 
  border: 2px solid var(--accent-color); 
  border-radius: 12px; 
  padding: 14px 28px; 
  color: var(--text-color); 
  background: var(--card-bg); 
  cursor: pointer; 
  font-weight: 700; 
  font-size: 1rem;
  transition: all 0.2s ease;
}

button#hello:hover, button#hello-about:hover { 
  background: var(--accent-color); 
  color: #ffffff;
  border-color: var(--accent-color);
  transform: translateY(-2px);
}

#message, #message-about {
  margin-top: 25px;
  font-weight: 600;
  font-style: italic;
  color: var(--accent-color);
}
