```javascript:app.js
const helloBtn = document.querySelector('#hello');
const helloAboutBtn = document.querySelector('#hello-about');
const messageEl = document.querySelector('#message');
const messageAboutEl = document.querySelector('#message-about');
const themeToggle = document.querySelector('#theme-toggle');
const icon = themeToggle.querySelector('.toggle-icon');

// Navigation Logic
const navHome = document.querySelector('#nav-home');
const navAbout = document.querySelector('#nav-about');
const homeView = document.querySelector('#home-view');
const aboutView = document.querySelector('#about-view');

function switchView(view) {
  if (view === 'home') {
    homeView.classList.remove('hidden');
    aboutView.classList.add('hidden');
    navHome.classList.add('active');
    navAbout.classList.remove('active');
  } else {
    homeView.classList.add('hidden');
    aboutView.classList.remove('hidden');
    navHome.classList.remove('active');
    navAbout.classList.add('active');
  }
}

navHome.addEventListener('click', () => switchView('home'));
navAbout.addEventListener('click', () => switchView('about'));

// Handle coffee interactions
const quotes = [
  "The first sip is always the best. ☕",
  "Brewing perfection, one bean at a time.",
  "Wake up and smell the roast.",
  "Coffee: because adulting is hard.",
  "A cup of coffee is a hug in a mug."
];

helloBtn?.addEventListener('click', () => {
  const randomQuote = quotes[Math.floor(Math.random() * quotes.length)];
  messageEl.textContent = randomQuote;
});

helloAboutBtn?.addEventListener('click', () => {
  const appreciationQuotes = [
    "Stay caffeinated! ☕",
    "May your cup always be full.",
    "To the bean that fuels the dream.",
    "Brewing memories, one cup at a time."
  ];
  const randomQuote = appreciationQuotes[Math.floor(Math.random() * appreciationQuotes.length)];
  messageAboutEl.textContent = randomQuote;
});

// Theme Logic
const currentTheme = localStorage.getItem('theme') || 'light';

if (currentTheme === 'dark') {
  document.documentElement.setAttribute('data-theme', 'dark');
  icon.textContent = '☀️';
}

themeToggle?.addEventListener('click', () => {
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

  if (isDark) {
    document.documentElement.removeAttribute('data-theme');
    localStorage.setItem('theme', 'light');
    icon.textContent = '🌙';
  } else {
    document.documentElement.setAttribute('data-theme', 'dark');
    localStorage.setItem('theme', 'dark');
    icon.textContent = '☀️';
  }
});
```

